import pytest
from your_module import camel_to_snake


class TestCamelToSnakeHappyPath:
    """Happy path tests for camel_to_snake function."""

    def test_simple_two_word(self):
        assert camel_to_snake("helloWorld") == "hello_world"

    def test_three_words(self):
        assert camel_to_snake("myVariableName") == "my_variable_name"

    def test_many_words(self):
        assert camel_to_snake("thisIsAVeryLongCamelCaseString") == "this_is_a_very_long_camel_case_string"

    def test_already_snake_case(self):
        result = camel_to_snake("already_snake_case")
        assert result == "already_snake_case"

    def test_all_lowercase(self):
        result = camel_to_snake("lowercase")
        assert result == "lowercase"

    def test_all_uppercase(self):
        result = camel_to_snake("UPPERCASE")
        assert result == "uppercase"


class TestCamelToSnakeEdgeCases:
    """Edge case tests for camel_to_snake function."""

    def test_empty_string(self):
        assert camel_to_snake("") == ""

    def test_single_lowercase_char(self):
        assert camel_to_snake("a") == "a"

    def test_single_uppercase_char(self):
        assert camel_to_snake("A") == "a"

    def test_single_word_no_transition(self):
        assert camel_to_snake("word") == "word"

    def test_string_with_numbers(self):
        assert camel_to_snake("test123Case") == "test123_case"
        assert camel_to_snake("user123Id") == "user123_id"

    def test_starts_with_uppercase(self):
        assert camel_to_snake("MyClass") == "my_class"
        assert camel_to_snake("HTTPRequest") == "http_request"

    def test_ends_with_uppercase(self):
        assert camel_to_snake("testCaseA") == "test_case_a"
        assert camel_to_snake("getAPI") == "get_api"

    def test_consecutive_uppercase_mid_word(self):
        # XMLParser -> xml_parser (insert before second uppercase)
        assert camel_to_snake("XMLParser") == "xml_parser"
        assert camel_to_snake("IOError") == "io_error"

    def test_all_consecutive_uppercase(self):
        assert camel_to_snake("XMLHTTPRequest") == "xml_http_request"

    def test_one_uppercase_one_lowercase(self):
        assert camel_to_snake("aB") == "a_b"

    def test_lowercase_uppercase_sequence(self):
        assert camel_to_snake("ABCdef") == "ab_cdef"

    def test_mixed_case_with_underscores(self):
        assert camel_to_snake("hello_World_Test") == "hello_world_test"

    def test_long_string(self):
        long_camel = "a" * 100 + "B" + "c" * 100 + "D"
        expected = "a" * 100 + "_b" + "c" * 100 + "_d"
        assert camel_to_snake(long_camel) == expected


class TestCamelToSnakeErrorCases:
    """Error case tests for camel_to_snake function."""

    def test_none_input(self):
        with pytest.raises(TypeError):
            camel_to_snake(None)

    def test_integer_input(self):
        with pytest.raises(TypeError):
            camel_to_snake(123)

    def test_list_input(self):
        with pytest.raises(TypeError):
            camel_to_snake(["hello", "world"])

    def test_dict_input(self):
        with pytest.raises(TypeError):
            camel_to_snake({"key": "value"})

    def test_float_input(self):
        with pytest.raises(TypeError):
            camel_to_snake(3.14)

    def test_tuple_input(self):
        with pytest.raises(TypeError):
            camel_to_snake(("a", "b"))
